import { test, expect } from '@playwright/test';

test.describe('Username Availability Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/signup');
  });

  test('should show available message for a unique username', async ({ page }) => {
    await page.getByLabel('Username').fill('uniqueUsername123');
    await page.getByLabel('Username').blur();
    await expect(page.getByText('Username is available')).toBeVisible();
  });

  test('should show taken message for an existing username', async ({ page }) => {
    await page.getByLabel('Username').fill('existingUsername');
    await page.getByLabel('Username').blur();
    await expect(page.getByText('Username is already taken')).toBeVisible();
  });
});
